CREATE INDEX `skill_security_state_vt_queue_priority_idx` ON `skill_security_state` (vt_priority DESC,open_security_report_count DESC,`updated_at`,`skill_id`,`vt_next_attempt_at`) WHERE "skill_security_state"."vt_eligibility" = 'eligible' AND "skill_security_state"."vt_status" IN ('pending_lookup', 'pending_upload', 'pending_analysis_poll');